    SELECT '13' AS state_fips, '239' AS county_fips, 'QUITMAN' AS county_name UNION ALL
    SELECT '26' AS state_fips, '141' AS county_fips, 'PRESQUE ISLE' AS county_name UNION ALL
    SELECT '48' AS state_fips, '505' AS county_fips, 'ZAPATA' AS county_name UNION ALL
    SELECT '20' AS state_fips, '071' AS county_fips, 'GREELEY' AS county_name UNION ALL
    SELECT '51' AS state_fips, '013' AS county_fips, 'ARLINGTON' AS county_name UNION ALL
    SELECT '08' AS state_fips, '111' AS county_fips, 'SAN JUAN' AS county_name
) c
JOIN dim_state s ON s.state_fips = c.state_fips;
